214	fn applet_does_not_leak_aggregate_or_other_applet_candidates() {
215	    // From within `status`, `busybox`'s `stop` subcommand and the applet roots
216	    // must never be offered.
217	    let candidates = complete_str(&["/usr/bin/status", ""]);
218	    assert!(!candidates.contains(&"stop".to_owned()));
