387	fn non_utf8_argv0_does_not_error() {
388	    use std::os::unix::ffi::OsStringExt;
389	
390	    // An argv0 whose file stem is not valid UTF-8 cannot name an applet; like
391	    // the parser it is treated as an ordinary binary name rather than failing,
392	    // so completion proceeds at the aggregate command's root.
393	    let mut cmd = multicall_cmd();
