290	#[derive(Debug, PartialEq, Eq, Clone)]
291	enum ParseState<'a> {
292	    /// Parsing a value done, there is no state to record.
293	    ValueDone,
294	
295	    /// Parsing a positional argument after `--`. `Pos(pos_index`, `takes_num_args`)
296	    Pos((usize, usize)),
297	
298	    /// Parsing a optional flag argument
299	    Opt(OptState<'a>),
300	}
301	
302	/// State kept while the values of an option are still being parsed.
303	#[derive(Debug, PartialEq, Eq, Clone)]
304	struct OptState<'a> {
305	    opt: &'a clap::Arg,
306	    /// Shell-word values consumed, counted the way the parser does so that
307	    /// [`ArgValueCompleter::complete_at`] keeps indexing shell arguments
308	    /// rather than delimiter-separated fragments.
309	    words: usize,
310	    /// Canonical possible-value names of the valid, committed fragments of
311	    /// the current occurrence. Only populated for strict delimited groups.
312	    used: Vec<String>,
313	    /// Whether the most recent shell word ended with the value delimiter, so
314	    /// the word under the cursor is still filling this group (and may not
315	    /// switch scope no matter how it is shaped).
316	    open: bool,
317	    /// Whether a committed fragment of the current group was invalid (empty,
318	    /// unknown, duplicated, or past the group's capacity). Such a group stays
319	    /// locked on value completion and never yields candidates or lets a later
320	    /// word switch scope.
321	    invalid: bool,
322	}
323	
324	impl<'a> OptState<'a> {
325	    fn new(opt: &'a clap::Arg) -> Self {
326	        Self {
327	            opt,
328	            words: 0,
329	            used: Vec::new(),
330	            open: false,
331	            invalid: false,
332	        }
333	    }
334	
335	    fn is_strict_group(&self) -> bool {
336	        is_strict_group_arg(self.opt)
337	    }
338	
339	    /// Maximum number of values the option accepts; for strict delimited
340	    /// groups this is the number of fragments allowed in one occurrence.
341	    fn capacity(&self) -> usize {
342	        self.opt.get_num_args().expect("built").max_values()
343	    }
344	
345	    /// Record a shell word as a value of this option.
346	    ///
347	    /// `attached` marks a value glued to its flag (`--opt=a,b`). For options
348	    /// whose delimiter is not a strict group, such a word counts every
349	    /// delimiter-separated fragment toward the value range; a space-separated
350	    /// word counts once. For strict groups the fragments are instead validated
351	    /// into `used`, except the empty slot still being typed after a trailing
352	    /// delimiter.
353	    fn observe(&mut self, word: &OsStr, attached: bool) {
354	        if !self.is_strict_group() {
355	            let count = if attached {
356	                attached_value_count(self.opt, word)
357	            } else {
358	                1
359	            };
360	            self.words += count;
361	            return;
362	        }
363	
364	        self.words += 1;
365	        if self.invalid {
366	            return;
367	        }
368	        let delimiter = self.opt.get_value_delimiter().expect("strict group");
369	        let capacity = self.capacity();
370	        self.open = word.to_string_lossy().ends_with(delimiter);
371	        let Some(word) = word.to_str() else {
372	            self.invalid = true;
373	            return;
374	        };
375	        let mut fragments = word.split(delimiter);
376	        if self.open {
377	            // A trailing delimiter opens the slot still being typed, so its
378	            // empty fragment is not a committed value.
379	            fragments.next_back();
380	        }
381	        for fragment in fragments {
382	            if self.used.len() >= capacity {
383	                self.invalid = true;
384	                break;
385	            }
386	            match canonical_possible_value(self.opt, fragment) {
387	                Some(name) if !self.used.contains(&name) => self.used.push(name),
388	                _ => {
389	                    // Empty (also a doubled delimiter), unknown, or duplicated
390	                    // fragment: the parser would reject this group.
391	                    self.invalid = true;
392	                    break;
393	                }
394	            }
395	        }
396	    }
397	
398	    /// Consume a value and return the state parsing should resume with.
399	    ///
400	    /// The delimiter separates several fragments within one shell word, so a
401	    /// word that does not end with the delimiter is a complete value group and
402	    /// ordinary parsing resumes on the next word. A trailing delimiter instead
403	    /// opens a fragment still being typed, and an invalid committed fragment
404	    /// cannot be salvaged; both keep the group locked on values. An empty
405	    /// attached value (`--opt=`) leaves the option waiting for its first value.
406	    fn finish(self) -> ParseState<'a> {
407	        if self.is_strict_group() {
408	            if self.words == 0 || self.invalid || self.open {
409	                ParseState::Opt(self)
410	            } else {
411	                ParseState::ValueDone
412	            }
413	        } else if self.words >= self.capacity() {
414	            ParseState::ValueDone
415	        } else {
416	            ParseState::Opt(self)
417	        }
418	    }
419	}
420	
421	/// Whether an option's values form a delimited group that can hold more than
422	/// one fragment and whose fragments are validated while typed.
423	///
424	/// Single-value options (a maximum of one) are excluded: their delimiter only
425	/// joins several suggestions into one word, so completed fragments are not
426	/// validated against each other.
427	fn is_strict_group_arg(arg: &clap::Arg) -> bool {
428	    arg.get_value_delimiter().is_some()
429	        && arg.get_num_args().expect("built").max_values() > 1
430	        && possible_values(arg).is_some()
431	}
432	
433	/// The canonical possible-value name for `fragment`, honoring aliases and the
434	/// argument's case-insensitivity, or `None` when it is not a legal value.
435	fn canonical_possible_value(arg: &clap::Arg, fragment: &str) -> Option<String> {
436	    let ignore_case = arg.is_ignore_case_set();
437	    possible_values(arg)?
438	        .find(|value| value.matches(fragment, ignore_case))
439	        .map(|value| value.get_name().to_owned())
440	}
441	
442	/// Complete the word under the cursor for a strict delimited group.
443	///
444	/// Fragments already committed in earlier shell words are read from `state`;
445	/// fragments committed within the word under the cursor are validated here.
446	/// The fragment still being typed is matched against the possible values, and
447	/// every suggestion keeps the typed prefix (prior fragments and delimiters).
448	/// Any empty, unknown, duplicated, or over-capacity fragment yields an empty
449	/// result.
450	fn complete_strict_group(cursor: &str, state: &OptState<'_>) -> Vec<CompletionCandidate> {
451	    debug!(
452	        "complete_strict_group: arg={:?}, cursor={cursor:?}, used={:?}, invalid={}",
453	        state.opt.get_id(),
454	        state.used,
455	        state.invalid
456	    );
457	    if state.invalid {
458	        return Vec::new();
459	    }
460	    let delimiter = state.opt.get_value_delimiter().expect("strict group");
461	    let capacity = state.capacity();
462	
463	    let ends_with_delimiter = cursor.ends_with(delimiter);
464	    let mut parts = cursor.split(delimiter);
465	    let typed = if ends_with_delimiter {
466	        // The cursor sits right after a delimiter: the trailing empty element
467	        // is the fresh fragment being typed, not a committed value.
468	        parts.next_back();
469	        ""
470	    } else {
471	        parts.next_back().unwrap_or("")
472	    };
473	
474	    let mut used = state.used.clone();
475	    for fragment in parts {
476	        if used.len() >= capacity {
477	            return Vec::new();
478	        }
479	        match canonical_possible_value(state.opt, fragment) {
480	            Some(name) if !used.contains(&name) => used.push(name),
481	            _ => return Vec::new(),
482	        }
483	    }
484	
485	    if used.len() >= capacity {
486	        // Every slot is taken; there is no room for another fragment.
487	        return Vec::new();
488	    }
489	
490	    // Retain the text typed before the current fragment, including the last
491	    // delimiter, so suggestions replace only the fragment under the cursor.
492	    let prefix = cursor
493	        .rfind(delimiter)
494	        .map(|pos| cursor[..pos + delimiter.len_utf8()].to_owned());
495	
496	    let possible = possible_values(state.opt).expect("strict group");
497	    let mut values = complete_candidates_str(typed, possible_value_candidates(possible));
498	    // A value already committed to the group cannot be repeated.
499	    values.retain(|candidate| {
500	        candidate
501	            .get_value()
502	            .to_str()
503	            .is_none_or(|name| !used.iter().any(|used| used == name))
504	    });
505	
506	    if let Some(prefix) = prefix {
507	        values = values
508	            .into_iter()
509	            .map(|comp| comp.add_prefix(prefix.clone()))
510	            .collect();
511	    }
512	    values = values
513	        .into_iter()
514	        .map(|comp| {
515	            if comp.get_tag().is_some() {
516	                comp
517	            } else {
518	                comp.tag(Some(state.opt.to_string().into()))
519	            }
520	        })
521	        .collect();
522	
523	    values
524	}
