526	fn complete_arg(
527	    arg: &clap_lex::ParsedArg<'_>,
528	    cmd: &clap::Command,
529	    current_dir: Option<&std::path::Path>,
530	    pos_index: usize,
531	    is_escaped: bool,
532	    state: ParseState<'_>,
533	    used_args: &[clap::Id],
534	) -> Result<Vec<CompletionCandidate>, std::io::Error> {
535	    debug!(
536	        "complete_arg: arg={:?}, cmd={:?}, current_dir={:?}, pos_index={:?}, state={:?}",
537	        arg,
538	        cmd.get_name(),
539	        current_dir,
540	        pos_index,
541	        state
542	    );
543	    let mut completions = Vec::<CompletionCandidate>::new();
544	
545	    match state {
546	        ParseState::ValueDone => {
547	            if !is_escaped {
548	                if let Ok(value) = arg.to_value() {
549	                    completions.extend(complete_subcommand(value, cmd));
550	                }
551	            }
552	
553	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
554	                completions.extend(complete_arg_value(
555	                    arg.to_value(),
556	                    positional,
557	                    current_dir,
558	                    0,
559	                ));
560	            }
561	            if !is_escaped {
562	                completions.extend(complete_option(arg, cmd, current_dir));
563	            }
564	        }
565	        ParseState::Pos((_, num_arg)) => {
566	            if let Some(positional) = find_positional(cmd, pos_index, is_escaped) {
567	                completions.extend(complete_arg_value(
568	                    arg.to_value(),
569	                    positional,
570	                    current_dir,
571	                    num_arg.saturating_sub(1),
572	                ));
573	                if !is_escaped
574	                    && positional
575	                        .get_num_args()
576	                        .is_some_and(|num_args| num_arg >= num_args.min_values())
577	                {
578	                    completions.extend(complete_option(arg, cmd, current_dir));
579	                }
580	            }
581	        }
582	        ParseState::Opt(state) => {
583	            if state.is_strict_group() {
584	                // Every word belongs to the pending delimited group until it is
585	                // complete; it is never an option, positional, or subcommand.
586	                if let Ok(cursor) = arg.to_value() {
587	                    completions.extend(complete_strict_group(cursor, &state));
588	                }
589	            } else {
590	                let opt = state.opt;
591	                // `words` counts already-consumed values; the word under the
592	                // cursor is the next one, so the option sees one more value.
593	                let count = state.words + 1;
594	                completions.extend(complete_arg_value(
595	                    arg.to_value(),
596	                    opt,
597	                    current_dir,
598	                    count.saturating_sub(1),
599	                ));
600	                let min = opt.get_num_args().map(|r| r.min_values()).unwrap_or(0);
601	                if count > min && can_switch_to_other_arg(opt, arg) {
602	                    // The option's required values are satisfied and this word
603	                    // would be parsed as a new flag rather than another value, so
604	                    // also complete it as a positional, flag, option or subcommand.
605	                    completions.extend(complete_arg(
606	                        arg,
607	                        cmd,
608	                        current_dir,
609	                        pos_index,
610	                        is_escaped,
611	                        ParseState::ValueDone,
612	                        used_args,
613	                    )?);
614	                }
615	            }
616	        }
617	    }
618	    filter_unavailable_args(&mut completions, cmd, used_args);
619	    if completions.iter().any(|a| !a.is_hide_set()) {
620	        completions.retain(|a| !a.is_hide_set());
621	    }
622	    dedup_argument_candidates(&mut completions, arg.is_empty());
623	
624	    let mut tags = Vec::new();
625	    for candidate in &completions {
626	        let tag = candidate.get_tag().cloned();
627	        if !tags.contains(&tag) {
628	            tags.push(tag);
629	        }
630	    }
631	    completions.sort_by_key(|c| {
632	        (
633	            tags.iter().position(|t| c.get_tag() == t.as_ref()),
634	            c.get_display_order(),
635	        )
636	    });
637	
638	    Ok(completions)
639	}
