848	fn rsplit_delimiter<'s, 'o>(
849	    value: Result<&'s str, &'o OsStr>,
850	    delimiter: Option<char>,
851	) -> Option<(Option<&'s str>, Result<&'s str, &'o OsStr>)> {
852	    let delimiter = delimiter?;
853	    let value = value.ok()?;
854	    let pos = value.rfind(delimiter)?;
855	    let (prefix, value) = value.split_at(pos + delimiter.len_utf8());
856	    Some((Some(prefix), Ok(value)))
857	}
