889	fn complete_subcommand(value: &str, cmd: &clap::Command) -> Vec<CompletionCandidate> {
890	    debug!(
891	        "complete_subcommand: cmd={:?}, value={:?}",
892	        cmd.get_name(),
893	        value
894	    );
895	
896	    let mut scs: Vec<CompletionCandidate> = subcommands(cmd)
897	        .into_iter()
898	        .filter(|x| x.get_value().starts_with(value))
899	        .collect();
900	    if cmd.is_allow_external_subcommands_set() {
901	        let external_completer = cmd.get::<SubcommandCandidates>();
902	        if let Some(completer) = external_completer {
903	            scs.extend(complete_value_candidates_str(
904	                value,
905	                completer.value_candidates(),
906	            ));
907	        }
908	    }
909	
910	    scs.dedup();
911	    scs
912	}
