914	/// Gets all the long options, their visible aliases and flags of a [`clap::Command`] with formatted `--` prefix.
915	/// Includes `help` and `version` depending on the [`clap::Command`] settings.
916	fn longs_and_visible_aliases(p: &clap::Command) -> Vec<CompletionCandidate> {
917	    debug!("longs: name={}", p.get_name());
918	
919	    p.get_arguments()
920	        .filter_map(|a| {
921	            a.get_long_and_visible_aliases().map(|longs| {
922	                longs
923	                    .into_iter()
924	                    .map(|s| populate_arg_candidate(CompletionCandidate::new(format!("--{s}")), a))
925	            })
926	        })
927	        .flatten()
928	        .collect()
929	}
