968	fn populate_arg_candidate(candidate: CompletionCandidate, arg: &clap::Arg) -> CompletionCandidate {
969	    candidate
970	        .help(arg.get_help().cloned())
971	        .id(Some(format!("arg::{}", arg.get_id())))
972	        .tag(Some(
973	            arg.get_help_heading()
974	                .unwrap_or("Options")
975	                .to_owned()
976	                .into(),
977	        ))
978	        .display_order(Some(arg.get_display_order()))
979	        .hide(arg.is_hide_set())
