994	///
995	/// Subcommand `rustup toolchain install` would be converted to
996	/// `("install", "rustup toolchain install")`.
997	fn subcommands(p: &clap::Command) -> Vec<CompletionCandidate> {
998	    debug!("subcommands: name={}", p.get_name());
999	    debug!("subcommands: Has subcommands...{:?}", p.has_subcommands());
1000	    p.get_subcommands()
1001	        .flat_map(|sc| {
1002	            sc.get_name_and_visible_aliases()
1003	                .into_iter()
1004	                .map(|s| populate_command_candidate(s, p, sc))
1005	                .chain(
1006	                    sc.get_aliases()
1007	                        .map(|s| populate_command_candidate(s, p, sc).hide(true)),
1008	                )
1009	        })
1010	        .collect()
1011	}
1012	
1013	fn populate_command_candidate(
1014	    candidate_name: &str,
1015	    cmd: &clap::Command,
1016	    subcommand: &clap::Command,
1017	) -> CompletionCandidate {
1018	    CompletionCandidate::new(candidate_name.to_owned())
1019	        .help(subcommand.get_about().cloned())
1020	        .id(Some(format!("command::{candidate_name}")))
1021	        .tag(Some(
1022	            cmd.get_subcommand_help_heading()
1023	                .unwrap_or("Commands")
1024	                .to_owned()
1025	                .into(),
1026	        ))
1027	        .display_order(Some(subcommand.get_display_order()))
1028	        .hide(subcommand.is_hide_set())
1029	}
