1031	/// Parse the short flags and find the first `takes_values` option.
1032	///
1033	/// Returns the raw leading flags, every matched argument, the first
1034	/// `takes_values` option (if any), and the remaining unparsed flags.
1035	fn parse_shortflags<'c, 's>(
1036	    cmd: &'c clap::Command,
1037	    mut short: clap_lex::ShortFlags<'s>,
1038	) -> (
1039	    String,
1040	    Vec<&'c clap::Arg>,
1041	    Option<&'c clap::Arg>,
1042	    clap_lex::ShortFlags<'s>,
1043	) {
1044	    let takes_value_opt;
1045	    let mut matched_opts = Vec::new();
1046	    let mut leading_flags = String::new();
1047	    // Find the first takes_values option.
1048	    loop {
1049	        match short.next_flag() {
1050	            Some(Ok(opt)) => {
1051	                leading_flags.push(opt);
1052	                let opt = cmd.get_arguments().find(|a| is_short_match(a, opt));
1053	                if let Some(opt) = opt {
1054	                    matched_opts.push(opt);
1055	                }
1056	                if opt
1057	                    .map(|o| o.get_num_args().expect("built").takes_values())
1058	                    .unwrap_or(false)
1059	                {
1060	                    takes_value_opt = opt;
1061	                    break;
1062	                }
1063	            }
1064	            Some(Err(_)) | None => {
1065	                takes_value_opt = None;
1066	                break;
1067	            }
1068	        }
1069	    }
1070	
1071	    (leading_flags, matched_opts, takes_value_opt, short)
1072	}
1073	
1074	/// Whether the argument can be addressed by the long flag `flag`,
1075	/// including visible and hidden aliases.
1076	fn is_long_match(arg: &clap::Arg, flag: &str) -> bool {
1077	    arg.get_long() == Some(flag)
1078	        || arg
1079	            .get_all_aliases()
1080	            .is_some_and(|aliases| aliases.contains(&flag))
1081	}
1082	
1083	/// Whether the argument can be addressed by the short flag `flag`,
1084	/// including visible and hidden aliases.
1085	fn is_short_match(arg: &clap::Arg, flag: char) -> bool {
1086	    arg.get_short() == Some(flag)
1087	        || arg
1088	            .get_all_short_aliases()
1089	            .is_some_and(|aliases| aliases.contains(&flag))
1090	}
1091	
1092	/// Remove argument candidates that are unavailable given the arguments
1093	/// already present on the command line.
1094	///
1095	/// Two rules apply:
1096	/// - Non-multiple argument groups: once any member of such a group is on the
1097	///   command line, every member of that group (including the selected one and
1098	///   all of its aliases) is removed, mirroring the parser's one-of constraint.
1099	/// - Explicit conflicts: a candidate that conflicts with an already-used
1100	///   argument is removed; conflicts only need to be declared on one side.
1101	///
1102	/// Anything that is not an argument candidate (positional values,
1103	/// subcommands, custom candidates) is left untouched.
1104	fn filter_unavailable_args(
1105	    completions: &mut Vec<CompletionCandidate>,
1106	    cmd: &clap::Command,
1107	    used_args: &[clap::Id],
1108	) {
1109	    if used_args.is_empty() {
1110	        return;
1111	    }
1112	
1113	    // Members of non-multiple groups that already have a member present.
1114	    let mut excluded_by_group = std::collections::HashSet::<clap::Id>::new();
1115	    for group in cmd.get_groups().filter(|group| !group.is_multiple_set()) {
1116	        let members: Vec<&clap::Id> = group.get_args().collect();
1117	        if members
1118	            .iter()
1119	            .any(|id| used_args.iter().any(|used| used == *id))
1120	        {
1121	            excluded_by_group.extend(members.into_iter().cloned());
1122	        }
1123	    }
1124	
1125	    completions.retain(|candidate| {
1126	        let Some(arg) = candidate
1127	            .get_id()
1128	            .and_then(|id| id.strip_prefix("arg::"))
1129	            .and_then(|id| cmd.get_arguments().find(|a| a.get_id() == id))
1130	        else {
1131	            return true;
1132	        };
1133	        if excluded_by_group.contains(arg.get_id()) {
1134	            return false;
1135	        }
1136	        !used_args.iter().any(|used_id| {
1137	            cmd.get_arguments()
1138	                .find(|a| a.get_id() == used_id)
1139	                .is_some_and(|used| args_conflict(cmd, arg, used))
1140	        })
1141	    });
1142	}
1143	
1144	/// Record an argument seen on the command line, keeping the first occurrence
1145	/// only so that repeating a flag neither alters filtering nor restores
1146	/// candidates already excluded.
1147	fn record_used_arg(used_args: &mut Vec<clap::Id>, id: &clap::Id) {
1148	    if !used_args.iter().any(|used| used == id) {
1149	        used_args.push(id.clone());
1150	    }
1151	}
1152	
1153	/// De-duplicate flag candidates.
1154	///
1155	/// With an empty word every long spelling of an argument (its long name and
1156	/// visible aliases) is offered, while short spellings are still collapsed to
1157	/// the canonical short and dropped for arguments that also have a long form.
1158	/// Once a prefix is typed at most one spelling of an argument can match, so
1159	/// candidates are de-duplicated by argument id as before.
1160	fn dedup_argument_candidates(completions: &mut Vec<CompletionCandidate>, empty_word: bool) {
1161	    if empty_word {
1162	        let long_ids: std::collections::HashSet<String> = completions
1163	            .iter()
1164	            .filter(|candidate| {
1165	                candidate.get_id().is_some() && candidate.get_value().starts_with("--")
1166	            })
1167	            .filter_map(|candidate| candidate.get_id().cloned())
1168	            .collect();
1169	        let mut seen_short_ids = std::collections::HashSet::new();
1170	        completions.retain(|candidate| {
1171	            let Some(id) = candidate.get_id() else {
1172	                return true;
1173	            };
1174	            if candidate.get_value().starts_with("--") {
1175	                // Keep the long name and every visible alias.
1176	                true
1177	            } else if long_ids.contains(id) {
1178	                // Prefer the long forms over the short ones.
1179	                false
1180	            } else {
1181	                seen_short_ids.insert(id.clone())
1182	            }
1183	        });
1184	    } else {
1185	        let mut seen_ids = std::collections::HashSet::new();
1186	        completions.retain(|candidate| {
1187	            if let Some(id) = candidate.get_id().cloned() {
1188	                seen_ids.insert(id)
1189	            } else {
1190	                true
1191	            }
1192	        });
1193	    }
1194	}
1195	
1196	/// Whether `first` and `second` conflict, no matter which one declares it.
1197	fn args_conflict(cmd: &clap::Command, first: &clap::Arg, second: &clap::Arg) -> bool {
1198	    cmd.get_arg_conflicts_with(first)
1199	        .iter()
1200	        .any(|c| c.get_id() == second.get_id())
1201	        || cmd
1202	            .get_arg_conflicts_with(second)
1203	            .iter()
1204	            .any(|c| c.get_id() == first.get_id())
1205	}
1206	
1207	/// The positional the parser would fill at `pos_index`.
1208	///
1209	/// A `last(true)` positional only exists after `--`; before the terminator
1210	/// the parser rejects values for it, so it must not be completed.
1211	fn find_positional(cmd: &clap::Command, pos_index: usize, is_escaped: bool) -> Option<&clap::Arg> {
1212	    cmd.get_positionals()
1213	        .find(|p| p.get_index() == Some(pos_index) && (is_escaped || !p.is_last_set()))
1214	}
1215	
1216	/// Parse the positional arguments. Return the new state and the new positional index.
1217	fn parse_positional<'a>(
1218	    cmd: &clap::Command,
1219	    pos_index: usize,
1220	    is_escaped: bool,
1221	    state: ParseState<'a>,
1222	) -> (ParseState<'a>, usize) {
1223	    let pos_arg = cmd
1224	        .get_positionals()
1225	        .find(|p| p.get_index() == Some(pos_index));
1226	    let num_args = pos_arg
1227	        .and_then(|a| a.get_num_args().map(|r| r.max_values()))
1228	        .unwrap_or(1);
1229	
1230	    let update_state_with_new_positional = |pos_index| -> (ParseState<'a>, usize) {
1231	        if num_args > 1 {
1232	            (ParseState::Pos((pos_index, 1)), pos_index)
1233	        } else {
1234	            if is_escaped {
1235	                (ParseState::Pos((pos_index, 1)), pos_index + 1)
1236	            } else {
1237	                (ParseState::ValueDone, pos_index + 1)
1238	            }
1239	        }
1240	    };
1241	    match state {
1242	        ParseState::ValueDone => {
1243	            update_state_with_new_positional(pos_index)
1244	        },
1245	        ParseState::Pos((prev_pos_index, num_arg)) => {
1246	            if prev_pos_index == pos_index {
1247	                if num_arg + 1 < num_args {
1248	                    (ParseState::Pos((pos_index, num_arg + 1)), pos_index)
1249	                } else {
1250	                    if is_escaped {
1251	                        (ParseState::Pos((pos_index, 1)), pos_index + 1)
1252	                    } else {
1253	                        (ParseState::ValueDone, pos_index + 1)
1254	                    }
1255	                }
1256	            } else {
1257	                update_state_with_new_positional(pos_index)
1258	            }
1259	        }
1260	        ParseState::Opt(..) => unreachable!(
1261	            "This branch won't be hit,
1262	            because ParseState::Opt should not be seen as a positional argument and passed to this function."
1263	        ),
1264	    }
1265	}
1266	
1267	fn pos_allows_hyphen(cmd: &clap::Command, pos_index: usize) -> bool {
1268	    cmd.get_positionals()
1269	        .find(|a| a.get_index() == Some(pos_index))
1270	        .map(|p| p.is_allow_hyphen_values_set())
1271	        .unwrap_or(false)
1272	}
1273	
1274	/// How many of an option's values an attached `=value` (or `-ovalue`) accounts
1275	/// for, honoring the value delimiter.
1276	fn attached_value_count(opt: &clap::Arg, value: &OsStr) -> usize {
1277	    match (opt.get_value_delimiter(), value.to_str()) {
1278	        (Some(delimiter), Some(value)) => value.split(delimiter).count(),
1279	        _ => 1,
1280	    }
1281	}
1282	
1283	fn opt_allows_hyphen(state: &ParseState<'_>, arg: &clap_lex::ParsedArg<'_>) -> bool {
1284	    let val = arg.to_value_os();
1285	    if val.starts_with("-") {
1286	        if let ParseState::Opt(state) = state {
1287	            return state.opt.is_allow_hyphen_values_set();
1288	        }
1289	    }
1290	
1291	    false
1292	}
1293	
1294	/// Whether `arg` is the standalone value terminator of a pending option.
1295	///
1296	/// Like the parser, an attached value (`--opt=;`) is not a terminator: the
1297	/// word must consist of the terminator alone.
1298	fn is_value_terminator(opt: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1299	    opt.get_value_terminator()
1300	        .is_some_and(|term| arg.to_value_os() == OsStr::new(term.as_str()))
1301	}
1302	
1303	/// Whether the parser would route this word through flag/escape parsing before
1304	/// a pending option gets to consume it as a value.
1305	fn is_flag_like(arg: &clap_lex::ParsedArg<'_>) -> bool {
1306	    arg.is_escape() || arg.to_long().is_some() || arg.to_short().is_some()
1307	}
1308	
1309	/// Whether a word can terminate a still-open multi-value option and start a
1310	/// new argument instead, the way the parser would read it.
1311	///
1312	/// While an option still owes values, the parser greedily consumes every plain
1313	/// word as one of its values; only flag-like words can switch to another
1314	/// argument. An option that accepts hyphen values consumes those too.
1315	fn can_switch_to_other_arg(pending: &clap::Arg, arg: &clap_lex::ParsedArg<'_>) -> bool {
1316	    if arg.is_escape() {
1317	        // `--` cancels every pending option unless its values may start with `--`.
1318	        return !pending.is_allow_hyphen_values_set();
1319	    }
1320	    if !arg.to_value_os().starts_with("-") {
1321	        // A plain word is always another value of the pending option.
1322	        return false;
1323	    }
1324	    if pending.is_allow_hyphen_values_set() {
1325	        return false;
1326	    }
1327	    // `-` is a stdio/value, not a flag.
1328	    if arg.is_stdio() {
1329	        return false;
1330	    }
1331	    // Both long and short flag styles can start a new argument; unknown flags
1332	    // still switch (and error during parsing) rather than become option values.
1333	    arg.to_long().is_some() || arg.to_short().is_some()
1334	}
