#![cfg(feature = "unstable-dynamic")]

use std::ffi::OsString;

use clap::{builder::PossibleValue, Arg, Command};
use clap_complete::engine::CompletionCandidate;

fn status_cmd() -> Command {
    Command::new("status")
        .about("Show status")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("config")
                .long("config")
                .global(true)
                .value_parser([PossibleValue::new("dev"), PossibleValue::new("prod")]),
        )
        .arg(
            Arg::new("format")
                .long("format")
                .value_parser([PossibleValue::new("text"), PossibleValue::new("json")]),
        )
}

fn aggregate_cmd() -> Command {
    Command::new("aggregate")
        .multicall(true)
        .no_binary_name(true)
        .disable_help_flag(true)
        .disable_help_subcommand(true)
        .disable_version_flag(true)
        .subcommand(
            Command::new("busybox")
                .visible_alias("bb")
                .disable_help_flag(true)
                .disable_help_subcommand(true)
                .disable_version_flag(true)
                .arg(
                    Arg::new("config")
                        .long("config")
                        .global(true)
                        .value_parser([PossibleValue::new("dev"), PossibleValue::new("prod")]),
                )
                .subcommand(
                    Command::new("status")
                        .visible_alias("st")
                        .alias("legacy-status")
                        .about("Show status")
                        .disable_help_flag(true)
                        .disable_version_flag(true)
                        .arg(
                            Arg::new("format")
                                .long("format")
                                .value_parser([
                                    PossibleValue::new("text"),
                                    PossibleValue::new("json"),
                                ]),
                        ),
                )
                .subcommand(Command::new("stop").about("Stop the service")),
        )
        .subcommand(status_cmd())
}

fn complete(args: &[&str]) -> Result<Vec<String>, std::io::Error> {
    let args = args.iter().map(OsString::from).collect::<Vec<_>>();
    let index = args.len() - 1;
    clap_complete::engine::complete(&mut aggregate_cmd(), args, index, None).map(|cs| {
        cs.iter()
            .map(|c: &CompletionCandidate| c.get_value().to_string_lossy().into_owned())
            .collect()
    })
}

