    Arg::new("config")
        .long("config")
        .global(true)
        .value_parser([PossibleValue::new("dev"), PossibleValue::new("prod")])
}

fn status_inner() -> Command {
    Command::new("status")
        .about("Show status")
        .disable_help_flag(true)
        .disable_version_flag(true)
        .arg(
            Arg::new("format")
                .long("format")
                .value_parser([PossibleValue::new("text"), PossibleValue::new("json")]),
        )
        .arg(config_arg())
        .group(ArgGroup::new("config_group").arg("config"))
}

fn aggregate_cmd() -> Command {
    Command::new("aggregate")
        .multicall(true)
        .no_binary_name(true)
        .disable_help_flag(true)
        .disable_help_subcommand(true)
        .disable_version_flag(true)
        .subcommand(
            Command::new("busybox")
                .visible_alias("bb")
                .disable_help_flag(true)
                .disable_help_subcommand(true)
                .disable_version_flag(true)
