                        .visible_alias("st")
                        .alias("legacy-status"),
                )
                .subcommand(Command::new("stop").about("Stop the service")),
        )
        .subcommand(
            status_inner()
                .visible_alias("st")
                .alias("legacy-status"),
        )
}

fn complete(args: &[&str]) -> Result<Vec<String>, std::io::Error> {
    let args = args.iter().map(OsString::from).collect::<Vec<_>>();
    let index = args.len() - 1;
    clap_complete::engine::complete(&mut aggregate_cmd(), args, index, None).map(|cs| {
        cs.iter()
            .map(|c: &CompletionCandidate| c.get_value().to_string_lossy().into_owned())
            .collect()
    })
}

