#![cfg(feature = "unstable-dynamic")]

use std::ffi::OsString;

use clap_complete::engine::CompletionCandidate;

include!("multicall_no_binary_name/helpers.rs");

#[test]
fn scratch() {
    for args in [
        &["busybox", "status", ""][..],
        &["busybox", "status", "--"][..],
        &["/usr/bin/status", ""][..],
        &["/usr/bin/status", "--"][..],
        &["busybox", "st", ""][..],
        &["busybox", "legacy-status", ""][..],
        &["busybox", "--"][..],
        &["busybox", ""][..],
        &["busybox", "--config=prod", ""][..],
        &["busybox", "status", "--config=prod", ""][..],
    ] {
        let raw: Vec<OsString> = args.iter().map(OsString::from).collect();
        let idx = raw.len() - 1;
        let cs = clap_complete::engine::complete(&mut aggregate_cmd(), raw, idx, None).unwrap();
        for c in &cs {
            println!(
                "{args:?} => {:?} order={:?} tag={:?} hide={}",
